import { Effect } from "effect";
import { pollForToken } from "@/services/ai-hero-auth-service";
import { makeAction } from "@/services/route-action.server";

export const action = async (args: {
  request: Request;
  params: Record<string, string | undefined>;
}) => {
  const body = await args.request.json();
  const deviceCode = body.deviceCode as string;

  if (!deviceCode) {
    return Response.json({ error: "deviceCode is required" }, { status: 400 });
  }

  return makeAction({
    effect: () =>
      Effect.gen(function* () {
        const result = yield* pollForToken(deviceCode);
        return Response.json({
          success: true,
          userId: result.userId,
        });
      }).pipe(
        Effect.catchTag("AiHeroAuthError", (e) =>
          Effect.succeed(
            Response.json({ error: e.message, code: e.code }, { status: 400 })
          )
        )
      ),
  })(args);
};

import { Config, ConfigProvider, Console, Effect } from "effect";
import { redirect } from "react-router";

/**
 * Initiates Google OAuth2 flow for YouTube uploads.
 * Redirects to Google's consent screen with the youtube.upload scope.
 */
export const loader = async ({ request }: { request: Request }) => {
  const url = new URL(request.url);
  const returnTo = url.searchParams.get("returnTo") || "/";

  return Effect.gen(function* () {
    const clientId = yield* Config.string("GOOGLE_CLIENT_ID");

    // Build the OAuth redirect URI (callback endpoint)
    const origin = url.origin;
    const redirectUri = `${origin}/api/auth/google/callback`;

    // Build the Google OAuth authorization URL
    const authUrl = new URL("https://accounts.google.com/o/oauth2/v2/auth");
    authUrl.searchParams.set("client_id", clientId);
    authUrl.searchParams.set("redirect_uri", redirectUri);
    authUrl.searchParams.set("response_type", "code");
    authUrl.searchParams.set(
      "scope",
      "https://www.googleapis.com/auth/youtube.upload"
    );
    authUrl.searchParams.set("access_type", "offline");
    authUrl.searchParams.set("prompt", "consent");
    // Store returnTo in state so we can redirect back after auth
    authUrl.searchParams.set("state", returnTo);

    return redirect(authUrl.toString());
  }).pipe(
    Effect.tapErrorCause((e) => Console.log(e)),
    Effect.catchTag("ConfigError", () => {
      return Effect.die(
        new Response("Google OAuth not configured", { status: 500 })
      );
    }),
    Effect.withConfigProvider(ConfigProvider.fromEnv()),
    Effect.runPromise
  );
};

import { Config, ConfigProvider, Console, Data, Effect } from "effect";
import { redirect } from "react-router";
import { runtimeLive } from "@/services/layer.server";
import { LinkAuthOperationsService } from "@/services/db-link-auth-operations.server";

class DropboxOAuthError extends Data.TaggedError("DropboxOAuthError")<{
  message: string;
  code?: string;
}> {}

export const loader = async ({ request }: { request: Request }) => {
  const url = new URL(request.url);
  const code = url.searchParams.get("code");
  const state = url.searchParams.get("state") || "/";
  const error = url.searchParams.get("error");

  if (error) {
    console.error("Dropbox OAuth error:", error);
    return redirect(`${state}?error=oauth_${error}`);
  }

  if (!code) {
    console.error("No authorization code received");
    return redirect(`${state}?error=no_code`);
  }

  return Effect.gen(function* () {
    const appKey = yield* Config.string("DROPBOX_APP_KEY");
    const appSecret = yield* Config.string("DROPBOX_APP_SECRET");
    const linkAuthOps = yield* LinkAuthOperationsService;

    const origin = url.origin;
    const redirectUri = `${origin}/api/auth/dropbox/callback`;

    const tokenResponse = yield* Effect.tryPromise({
      try: async () => {
        const response = await fetch(
          "https://api.dropboxapi.com/oauth2/token",
          {
            method: "POST",
            headers: {
              "Content-Type": "application/x-www-form-urlencoded",
            },
            body: new URLSearchParams({
              code,
              grant_type: "authorization_code",
              client_id: appKey,
              client_secret: appSecret,
              redirect_uri: redirectUri,
            }),
          }
        );

        if (!response.ok) {
          const errorData = await response.text();
          throw new Error(`Token exchange failed: ${errorData}`);
        }

        return response.json() as Promise<{
          access_token: string;
          refresh_token?: string;
          expires_in: number;
          token_type: string;
        }>;
      },
      catch: (e) =>
        new DropboxOAuthError({
          message: e instanceof Error ? e.message : "Token exchange failed",
        }),
    });

    if (!tokenResponse.refresh_token) {
      return yield* new DropboxOAuthError({
        message: "No refresh token received from Dropbox",
        code: "no_refresh_token",
      });
    }

    const expiresAt = new Date(Date.now() + tokenResponse.expires_in * 1000);

    yield* linkAuthOps.upsertDropboxAuth({
      accessToken: tokenResponse.access_token,
      refreshToken: tokenResponse.refresh_token,
      expiresAt,
    });

    yield* Effect.logInfo("Dropbox OAuth tokens stored successfully");

    return redirect(state);
  }).pipe(
    Effect.tapErrorCause((e) => Console.log(e)),
    Effect.catchTag("ConfigError", () => {
      return Effect.succeed(redirect("/?error=oauth_not_configured"));
    }),
    Effect.catchTag("DropboxOAuthError", (e) => {
      console.error("Dropbox OAuth error:", e.message);
      return Effect.succeed(redirect(`${state}?error=oauth_failed`));
    }),
    Effect.withConfigProvider(ConfigProvider.fromEnv()),
    Effect.catchAll((e) => {
      console.error("OAuth callback error:", e);
      return Effect.succeed(redirect(`${state}?error=oauth_error`));
    }),
    runtimeLive.runPromise
  );
};

import { Config, ConfigProvider, Console, Effect } from "effect";
import { redirect } from "react-router";
import { runtimeLive } from "@/services/layer.server";
import { runRouteEffect } from "@/services/route-action.server";

export const loader = async ({ request }: { request: Request }) => {
  const url = new URL(request.url);
  const returnTo = url.searchParams.get("returnTo") || "/";

  return Effect.gen(function* () {
    const appKey = yield* Config.string("DROPBOX_APP_KEY");

    const origin = url.origin;
    const redirectUri = `${origin}/api/auth/dropbox/callback`;

    const authUrl = new URL("https://www.dropbox.com/oauth2/authorize");
    authUrl.searchParams.set("client_id", appKey);
    authUrl.searchParams.set("redirect_uri", redirectUri);
    authUrl.searchParams.set("response_type", "code");
    authUrl.searchParams.set("token_access_type", "offline");
    authUrl.searchParams.set("state", returnTo);

    return redirect(authUrl.toString());
  }).pipe(
    Effect.tapErrorCause((e) => Console.log(e)),
    Effect.catchTag("ConfigError", () => {
      return Effect.die(
        new Response("Dropbox OAuth not configured", { status: 500 })
      );
    }),
    Effect.withConfigProvider(ConfigProvider.fromEnv()),
    (effect) => runRouteEffect(runtimeLive, effect)
  );
};
